# STEP J1-e2: writes src/roads/junction/J1ArmData.ts (arm centrelines, finished heights, structure ranges) from docs/j1c*_align.json, j1c*_profile.json, j1_structures_*.json
# Run: python3 tools/j1-arm-data.py        (do not edit the generated file by hand)
import json, math
ARMS = [('N','j1c4b_align.json','j1c4c_profile.json','j1_structures_NW.json'),('E','j1c7b_align.json','j1c7c_profile.json','j1_structures_E.json'),
        ('S','j1c6b_align.json','j1c6c_profile.json','j1_structures_S.json'),('W','j1c5b_align.json','j1c5c_profile.json','j1_structures_NW.json')]
S0, SJ, STEP = 270, 340, 10
def lvl(p, s):
    for v in p:
        if v['Lc'] > 0 and abs(s - v['s']) <= v['Lc'] / 2:
            s0 = v['s'] - v['Lc'] / 2
            return v['y'] + v['g1'] * (s - v['s']) + (v['g2'] - v['g1']) / (2 * v['Lc']) * (s - s0) ** 2
    k = 0
    while k + 1 < len(p) and s > p[k + 1]['s'] - p[k + 1]['Lc'] / 2: k += 1
    v = p[k]; g = v['g2'] if s >= v['s'] else v['g1']
    return v['y'] + g * (s - v['s'])
out = ['// GENERATED by tools/j1-arm-data.py (STEP J1-e2). Do not edit: rerun the tool. Centrelines of the four M8 arms of J1 from s = 270 m (end of the lane zone) to the T on the ring,',
       '// finished surface heights (J1-c4c / c5c / c6c / c7c profiles), and the structure ranges of 6.1d (station s, m from the J1 centre). Points every 10 m, last point = the T on the ring.',
       'export interface J1ArmData { name: string; s: number[]; pts: number[][]; ys: number[]; structs: number[][] }', 'export const J1_ARM_DATA: J1ArmData[] = [']
for tag, af, pf, sf in ARMS:
    A = json.load(open('docs/' + af)); P = json.load(open('docs/' + pf)); S = json.load(open('docs/' + sf))
    sm = A['samples']; rows = P['rows']; assert len(sm) == len(rows)
    for i in (0, 40, len(rows) - 1):  # sanity: profile level of the rows equals the PVI table
        assert abs(lvl(P['pvi'], rows[i][0]) - rows[i][2]) < 0.03, (tag, i, lvl(P['pvi'], rows[i][0]), rows[i][2])
    hx, hz = sm[1][1] - sm[0][1], sm[1][2] - sm[0][2]; hl = math.hypot(hx, hz); hx /= hl; hz /= hl
    pts, ys, ss = [], [], []
    for s in range(S0, SJ, STEP):
        d = SJ - s; pts.append([round(sm[0][1] - hx * d, 2), round(sm[0][2] - hz * d, 2)]); ys.append(round(lvl(P['pvi'], s), 3)); ss.append(s)
    idx = list(range(0, len(rows), STEP // 5)); 
    if idx[-1] != len(rows) - 1: idx.append(len(rows) - 1)
    for i in idx: pts.append([round(sm[i][1], 2), round(sm[i][2], 2)]); ys.append(round(rows[i][2], 3)); ss.append(round(rows[i][0], 2))
    st = [[round(q['s0'], 1), round(q['s1'], 1)] for q in S[tag]['structures']]
    out.append(f"  {{ name: 'J1-{tag}', s: {json.dumps(ss)}, pts: {json.dumps(pts)}, ys: {json.dumps(ys)}, structs: {json.dumps(st)} }},")
out.append('];')
open('src/roads/junction/J1ArmData.ts', 'w', newline='').write('\n'.join(out) + '\n')
print('written', sum(len(x) for x in out))
